import '@fontsource/public-sans/400.css';
import '@fontsource/public-sans/700.css';
import '../styles/global.css';
import EmailCapture from '../components/EmailCapture.astro';
import Analytics from '@vercel/analytics/astro';

interface Props {
  title: string;
  description?: string;
  current: 'week' | 'next' | 'last' | 'about' | 'event' | 'city';
  canonicalPath?: string;
  ogType?: string;
  jsonLd?: object | object[] | null;
  noindex?: boolean;
}

const SITE = 'https://www.thisweeksouthbay.com';

function normalizePath(path: string): string {
  if (!path || path === '/') return '/';
  const withLeading = path.startsWith('/') ? path : `/${path}`;
  const stripped = withLeading.replace(/\/+$/, '');
  return stripped || '/';
}

const {
  title,
  description = 'Monday email. 7am. Nights out, not news. Updated daily. Hermosa, Manhattan, Redondo, El Segundo, Torrance.',
  current,
  canonicalPath,
  ogType = 'website',
  jsonLd = null,
  noindex = false,
} = Astro.props;

const path = normalizePath(canonicalPath ?? Astro.url.pathname);
const canonicalUrl = path === '/' ? `${SITE}/` : `${SITE}${path}`;
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="google-site-verification" content="sFUgLPOn7SERvrTTy97EW-RBKFOsiMqq5W4ovtlomfE" />
    <meta name="description" content={description} />
    {noindex ? <meta name="robots" content="noindex" /> : null}
    <link rel="canonical" href={canonicalUrl} />
    <meta property="og:title" content={title} />
    <meta property="og:description" content={description} />
    <meta property="og:url" content={canonicalUrl} />
    <meta property="og:type" content={ogType} />
    <meta property="og:site_name" content="This Week South Bay" />
    <meta property="og:locale" content="en_US" />
    <meta name="twitter:card" content="summary" />
    <meta name="twitter:title" content={title} />
    <meta name="twitter:description" content={description} />
    <meta name="generator" content={Astro.generator} />
    <title>{title}</title>
    {
      jsonLd ? (
        <script type="application/ld+json" set:html={JSON.stringify(jsonLd)} />
      ) : null
    }
    <Analytics />
  </head>
  <body>
    <div class="page">
      <header class="chrome">
        <div class="chrome-start">
          <a class="wordmark" href="/">This Week</a>
          <nav class="nav" aria-label="Site">
            <a href="/" aria-current={current === 'week' ? 'page' : undefined}>This Week</a>
            <a href="/next-week" aria-current={current === 'next' ? 'page' : undefined}>Next Week</a>
            <a href="/last-week" aria-current={current === 'last' ? 'page' : undefined}>Last Week</a>
            <a href="/about" aria-current={current === 'about' ? 'page' : undefined}>About</a>
          </nav>
        </div>
        <a class="signup-jump" href="#signup">Monday email. 7am.</a>
      </header>

      <main class="main">
        <slot />
      </main>

      <footer class="foot">
        <EmailCapture id="signup" />
        <p class="foot-url">
          <a href="https://thisweeksouthbay.beehiiv.com">thisweeksouthbay.beehiiv.com</a>
        </p>
      </footer>
    </div>
  </body>
</html>

:root {
  --cream: #faf7f0;
  --ink: #121212;
  --muted: #464646;
  --bar: 3px;
  --page: 1.25rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  background: var(--cream);
  color: var(--ink);
  overflow-x: clip;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  font-family: 'Public Sans', ui-sans-serif, system-ui, sans-serif;
  font-weight: 400;
  font-size: 1rem;
  line-height: 1.4;
  background: var(--cream);
  color: var(--ink);
  border-left: var(--bar) solid var(--ink);
  overflow-x: clip;
}

a {
  color: inherit;
  text-underline-offset: 0.12em;
}

a:hover {
  text-decoration-thickness: 2px;
}

:focus-visible {
  outline: 1px solid var(--ink);
  outline-offset: 3px;
}

.page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding-left: var(--page);
  padding-left: calc(var(--page) + env(safe-area-inset-left, 0px));
  padding-right: var(--page);
  padding-right: calc(var(--page) + env(safe-area-inset-right, 0px));
}

.chrome {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding-top: 1.1rem;
  padding-bottom: 1.1rem;
}

.wordmark {
  font-size: 0.68rem;
  font-weight: 400;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  width: fit-content;
}

.wordmark:hover {
  text-decoration: none;
}

.nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem 1.15rem;
}

.nav a {
  color: var(--ink);
  text-decoration: none;
}

.nav a[aria-current='page'] {
  text-decoration: underline;
}

.email {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.7rem;
}

.email input {
  appearance: none;
  width: 10.5rem;
  max-width: 100%;
  border: 0;
  border-bottom: 1px solid var(--ink);
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 0.95rem;
  padding: 0.15rem 0 0.2rem;
}

.email input::placeholder {
  color: var(--muted);
}

.email a {
  color: var(--muted);
  text-decoration: none;
  white-space: nowrap;
}

.email a:hover {
  text-decoration: underline;
}

.signup-jump {
  color: var(--muted);
  text-decoration: none;
  white-space: nowrap;
}

.signup-jump:hover {
